INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(125169, 'ruRU', '', 'Деве бы это не понравилось!', 24330),
(125170, 'ruRU', '', 'Ох, боже... ты и ВПРАВДУ соблазнителен!', 24330),
(125171, 'ruRU', '', 'Я больше не общаюсь с такими, как ты!', 24330),
(125172, 'ruRU', '', 'Хочешь поиграть? ТОГДА ИГРАЕМ!', 24330),
(125173, 'ruRU', '', 'Я пытался быть хорошим... правда!', 24330),
(125174, 'ruRU', '', 'Я... подвёл... Деву...', 24330),
(125175, 'ruRU', '', 'Быть хорошим... не окупается...', 24330),
(125176, 'ruRU', '', 'Я так рад, что Дева показала нам правильный путь!', 24330),
(125177, 'ruRU', '', 'Не знаю... я вроде как тоскую по старым временам.', 24330),
(125178, 'ruRU', '', 'Я изучаю продвинутую магию. Может, даже подам заявку в Кирин-Тор!', 24330),
(125179, 'ruRU', '', 'Изгони тёмные мысли из своего разума. Помни её учения!', 24330),
(125180, 'ruRU', '', 'Добродетель переоценена!', 24330),
(125182, 'ruRU', '', 'Стыд... СТЫД...', 24330),
(125183, 'ruRU', '', 'Нет искупления... для меня...', 24330),
(125184, 'ruRU', '', 'Ты сам напросился!', 24330),
(125185, 'ruRU', '', 'Уверен, тебе больше нравлюсь я такой!', 24330),
(125186, 'ruRU', '', 'Всегда... одно и то же...', 24330),
(125187, 'ruRU', '', 'Похоже, я... заслужил это.', 24330),
(125188, 'ruRU', '', 'Кого я обманываю? ЭТО настоящий я!', 24330),
(125189, 'ruRU', '', 'Я так доооолго не веселился подобным образом!', 24330),
(125198, 'ruRU', '', 'Истребитель $n! Мы только что получили срочное сообщение от одного из разведчиков Белата на Мардуме!', 24330),
(125199, 'ruRU', '', 'Леди С''тено спустилась помочь несколько часов назад, но это звучит серьёзно. Нам стоит последовать за ней?', 24330),
(125209, 'ruRU', '', 'Это лучшее, на что ты способен? Полагаю, эредары не славятся своим мастерством владения мечом, не так ли?', 24330),
(125217, 'ruRU', '', 'Будь осторожен, $c. Архимаг может не встретить тебя своим обычным весёлым нравом.', 24330),
(125220, 'ruRU', '', 'Истребитель $n! Мы получили срочное сообщение от одного из наших разведчиков на Мардуме!', 24330),
(125221, 'ruRU', '', 'Власть гримуара над ним в последнее время только усилилась. Он стал параноидальным и одержимым.', 24330),
(125222, 'ruRU', '', 'Я столькому научилась у Сильгрина, но мне ещё многое предстоит освоить.$b$bНадеюсь, этого будет достаточно, когда придёт время встретиться лицом к лицу с Элизандой.', 24330),
(125228, 'ruRU', '', 'Иллидари! Мы нужны на Мардуме. Выдвигаемся!', 24330),
(125234, 'ruRU', '', 'Не нужно прыгать — наши демолетучие мыши рады возможности размять крылья!', 24330),
(125244, 'ruRU', '', '<Образ Ли''лет выжидающе смотрит на тебя. Хочешь услышать сообщение, что он несёт?>', 24330),
(125245, 'ruRU', '', 'Пока без движения. Подозреваю, Элизанда вполне комфортно себя чувствует в нынешней обстановке города. Здесь тихо. Возможно, наш народ слишком напуган, чтобы заявить о себе после жестокости в Убывающем Полумесяце...$b$bМне не удалось найти Вантира. Его имя подозрительно отсутствует в наших обсуждениях.$b$bЗабавная деталь — Элизанда самая непунктуальная персона, которой мне когда-либо выпадало несчастье служить.$b$bЯ доложу снова, как только смогу. Береги себя, Талисра.', 24330),
(125271, 'ruRU', '', 'Как ты просила, я разузнала о ситуации в Крепости Оскверненных Душ. Похоже, твои усилия значительно замедлили перевозки. С сожалением сообщаю, что это, вероятно, не остановится без дальнейшего вмешательства.$b$bЕсть кое-какие разговоры о зачистке дезертиров после событий в Гавани Астравар. Предупреди своих людей быть начеку. К тебе может прибыть больше беглецов.$b$bИз более лёгких новостей — по дворцу прокатилась новая модная тенденция. Все одержимы тем, чтобы водружать на голову декоративных оранжевых птиц. Поистине озадачивает.$b$bКак всегда, я продолжаю искать нашего общего друга. Как только узнаю больше, свяжусь с тобой напрямую.$b$bДержись крепко, Первый Чародей.', 24330),
(125272, 'ruRU', '', 'Я так рада, что Вантир в безопасности. Передай ему мои наилучшие пожелания! Надеюсь скоро увидеться с ним лично.$b$bСитуация... становится напряжённой. Демонстрация сумеречных лилий всерьёз встревожила знать. Они не сходятся во мнении, как справиться с ситуацией, но насилие определённо рассматривается как вариант. Я переживаю за тех, кто всё ещё заперт в городе.$b$bЯ заметила какое-то движение на Променаде — возможно, они укрепляют эту область. Стоит присмотреть за этим.$b$bДоложу, когда у меня будет больше информации.', 24330),
(125273, 'ruRU', '', 'Твои новые союзники не остались незамеченными.$b$bНе знаю, где ты нашла такой отряд, но мне пришлось скрывать своё удовольствие от их успехов в проникновении на Променад.$b$bНастроение здесь всё более встревоженное. У знати больше нет иллюзий, что они могут избежать боя. Элизанда не позволит им стоять в стороне, пока Сурамар захлёстывают чужаки.$b$bЯ бы пока не стала считать победу решённой, друг мой.$b$bБудь осторожна и будь сильной. Скоро увидимся.', 24330),
(125274, 'ruRU', '', 'У меня немного времени. К сожалению, этот доклад будет коротким.$b$bЭлизанда в ярости. Она что-то планирует, но у меня пока нет подробностей.$b$bМои глаза и уши открыты, как всегда. Как только я узнаю, что она затевает, я свяжусь с тобой.$b$bБереги себя.', 24330),
(125284, 'ruRU', '', 'Вандел! Мы откликнулись на твой зов о помощи. Что случилось?', 24330),
(125286, 'ruRU', '', 'Мы найдём их. А что насчёт леди С''тено?', 24330),
(125298, 'ruRU', '', 'Звал?', 24330),
(125300, 'ruRU', '', 'Осторожно!', 24330),
(125301, 'ruRU', '', 'Ох, боже!', 24330);
